import{w as i}from"./delay-DoBGGSIn.js";import{k as o,l as h}from"./index-zBeX1xPY.js";const m={items:[{id:"all-or-nothing",name:"Tư duy tất cả hoặc không có gì",description:"Nhìn mọi chuyện theo hai cực trắng – đen, chỉ thấy thành công trọn vẹn hoặc thất bại hoàn toàn mà bỏ qua khoảng giữa.",example:'Bài thuyết trình tiếng Anh bị vấp hai chỗ, thế là mình nghĩ: "Hỏng hết rồi, mình làm tệ quá."',promptQuestion:'Nếu chấm trên thang 10 thay vì "đạt hoặc hỏng", phần nào trong việc này vẫn ổn?'},{id:"overgeneralization",name:"Khái quát hóa quá mức",description:"Từ một sự việc không như ý, mình rút ra kết luận rằng mọi chuyện sau này đều sẽ như vậy mãi.",example:'Điểm kiểm tra giữa kỳ thấp hơn kỳ vọng nên mình nghĩ: "Môn này chắc mình chẳng bao giờ học khá nổi."',promptQuestion:"Đây là một sự việc riêng lẻ hay thật sự lúc nào cũng xảy ra y hệt như vậy?"},{id:"mental-filter",name:"Lọc tiêu cực",description:"Chỉ tập trung vào một chi tiết chưa tốt và phóng lớn nó lên, làm lu mờ những phần tích cực xung quanh.",example:"Cô giáo khen bài viết mạch lạc nhưng góp ý sửa hai lỗi ngữ pháp, cả tối mình chỉ nghĩ về hai lỗi đó.",promptQuestion:"Ngoài chi tiết làm mình bận tâm, bức tranh đầy đủ hôm nay còn có những phần nào khác?"},{id:"disqualifying-positive",name:"Phủ nhận điều tích cực",description:"Tự gạt bỏ lời khen hoặc kết quả tốt của bản thân bằng cách cho rằng đó chỉ là may mắn hay chuyện nhỏ.",example:'Bạn cùng nhóm khen phần slide mình làm gọn gàng, mình lại đáp: "Có gì đâu, làm đại thôi mà."',promptQuestion:"Nếu một người bạn làm được đúng điều đó, mình có xem nhẹ công sức của bạn ấy không?"},{id:"jumping-to-conclusions",name:"Suy diễn vội vàng (đọc suy nghĩ / tiên đoán tương lai)",description:"Tự đoán chắc người khác đang nghĩ xấu về mình hoặc dự báo kết quả tệ khi chưa có bằng chứng rõ ràng.",example:'Nhắn tin hỏi bài tập nhóm từ trưa chưa thấy bạn trả lời, mình nghĩ ngay: "Chắc bạn ấy thấy mình phiền."',promptQuestion:"Còn những lý do bình thường nào khác có thể giải thích chuyện này mà mình chưa biết?"},{id:"magnification-catastrophizing",name:"Phóng đại hoặc coi nhẹ (thảm họa hóa)",description:"Thổi phồng một sai sót nhỏ thành thảm họa lớn, đồng thời thu nhỏ khả năng xoay xở của bản thân.",example:'Lỡ gửi nhầm file nháp cho giảng viên, mình hoảng lên nghĩ: "Chắc bị đánh rớt môn này mất."',promptQuestion:"Kể cả khi tình huống xấu xảy ra thật, bước nhỏ tiếp theo mình có thể làm để sửa là gì?"},{id:"emotional-reasoning",name:"Lập luận theo cảm xúc",description:"Tin rằng cảm xúc mình đang trải qua chính là sự thật khách quan về bản thân hoặc tình huống.",example:'Hôm nay thấy nặng nề và lo âu nên mình kết luận: "Mình thật sự vô dụng."',promptQuestion:"Cảm xúc này đang nói với mình điều gì, và dữ kiện thực tế có hoàn toàn giống vậy không?"},{id:"should-statements",name:'Tư duy "phải / nên"',description:'Đặt ra những quy tắc cứng nhắc cho bản thân hoặc người khác bằng chữ "phải", "lẽ ra", dễ tạo cảm giác tội lỗi hay bực bội.',example:'Mình luôn tự nhủ: "Sinh viên năm hai rồi thì phải tự tin nói trước lớp, không được run."',promptQuestion:'Nếu đổi chữ "phải" thành "mình mong muốn" hoặc "mình đang tập", áp lực có dịu bớt không?'},{id:"labeling",name:"Gán nhãn",description:"Dán một nhãn tiêu cực cố định lên bản thân hoặc người khác chỉ vì một hành động hay khoảnh khắc chưa trọn vẹn.",example:'Quên mang tài liệu thảo luận nhóm, mình tự gọi mình là "đứa cẩu thả".',promptQuestion:"Mình đang mô tả một hành động cụ thể vừa xảy ra, hay đang gắn nhãn cho cả con người mình?"},{id:"personalization",name:"Cá nhân hóa",description:"Tự nhận toàn bộ trách nhiệm về một chuyện ngoài tầm kiểm soát hoặc nghĩ phản ứng của người khác là do lỗi của mình.",example:'Không khí buổi họp nhóm hơi trầm lắng, mình liền nghĩ: "Chắc tại mình nói câu lúc nãy nên mọi người mới im."',promptQuestion:"Trong chuyện này có những yếu tố nào khác không thuộc về mình?"}]},l={items:[{id:"all-or-nothing",name:"All-or-nothing thinking",description:"Seeing situations in strict black-and-white terms—either complete success or total failure—with no middle ground.",example:'I stumbled twice during my English presentation, so I thought: "I ruined the whole thing."',promptQuestion:"If you rated this on a 0–10 scale instead of pass/fail, what parts still went reasonably well?"},{id:"overgeneralization",name:"Overgeneralization",description:"Taking one disappointing event as proof that things will always turn out this way.",example:'My midterm score was lower than I hoped, so I thought: "I will never be good at this subject."',promptQuestion:"Is this one specific moment, or is it truly guaranteed to repeat every time?"},{id:"mental-filter",name:"Mental filter",description:"Zooming in on a single negative detail while filtering out everything else that went fine.",example:"The lecturer praised my essay structure and noted two grammar slips; all evening I only replayed those two slips.",promptQuestion:"Besides the detail bothering you, what else was part of the full picture today?"},{id:"disqualifying-positive",name:"Disqualifying the positive",description:"Brushing off compliments or good outcomes as mere luck, coincidence, or nothing special.",example:'A teammate complimented my clean slides and I replied: "Not really, I just threw them together."',promptQuestion:"If a close friend achieved the same thing, would you dismiss their effort that quickly?"},{id:"jumping-to-conclusions",name:"Jumping to conclusions (mind reading / fortune telling)",description:"Assuming you know what others think of you or predicting a bad outcome without solid evidence.",example:'My classmate has not replied to my group-work message since noon, so I assumed: "They must find me annoying."',promptQuestion:"What ordinary, everyday explanations could also fit this situation?"},{id:"magnification-catastrophizing",name:"Magnification or minimization (catastrophizing)",description:"Blowing a mistake out of proportion while shrinking your own ability to handle it.",example:'I accidentally emailed a draft file to my lecturer and panicked: "I am definitely going to fail this course."',promptQuestion:"Even if a setback happened, what small practical step could you take next?"},{id:"emotional-reasoning",name:"Emotional reasoning",description:"Treating how you feel right now as objective proof of what is true about you or the situation.",example:'Because I feel heavy and anxious today, I conclude: "I am completely incapable."',promptQuestion:"What is this feeling trying to tell you, and do the actual facts match that conclusion?"},{id:"should-statements",name:'"Should" and "must" statements',description:"Holding rigid rules about how you or others ought to behave, often leading to guilt or frustration.",example:'I keep telling myself: "As a second-year student, I must speak up without ever feeling nervous."',promptQuestion:'If you soften "I must" to "I would prefer" or "I am practicing", how does the pressure change?'},{id:"labeling",name:"Labeling",description:"Attaching a fixed negative label to yourself or someone else based on one slip or tough moment.",example:'I forgot my discussion notes once and immediately called myself "careless and unreliable".',promptQuestion:"Are you describing one specific action, or defining your entire character by a single moment?"},{id:"personalization",name:"Personalization",description:"Taking full blame for something outside your control, or assuming someone else’s mood is about you.",example:'Our study group seemed quiet today, so I thought: "Everyone is silent because of something I said earlier."',promptQuestion:"What other factors outside your control might be playing a part here?"}]},g={async getAll(){return await i(),[...h().exerciseEntries].sort((t,e)=>e.createdAt.localeCompare(t.createdAt))},async getById(n){return await i(),h().exerciseEntries.find(e=>e.id===n)??null},async saveEntry(n){await i();const t=new Date().toISOString(),e={id:`ex-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,exerciseId:n.exerciseId,answers:n.answers,summary:n.summary,createdAt:t,updatedAt:t};return o(a=>{const s={...a.exerciseDrafts};return delete s[n.exerciseId],{...a,exerciseEntries:[e,...a.exerciseEntries],exerciseDrafts:s}}),e},async deleteEntry(n){await i(),o(t=>({...t,exerciseEntries:t.exerciseEntries.filter(e=>e.id!==n)}))},getDraft(n){return h().exerciseDrafts[n]??null},saveDraft(n){o(t=>({...t,exerciseDrafts:{...t.exerciseDrafts,[n.exerciseId]:n}}))},clearDraft(n){o(t=>{if(!t.exerciseDrafts[n])return t;const e={...t.exerciseDrafts};return delete e[n],{...t,exerciseDrafts:e}})}};export{m as a,l as d,g as j};
